\section{Sylvester-Gallai \& Edelstein-Kelly Configurations}\label{section: SG and EK configurations}

\subsection{Edelstein–Kelly configurations}

\begin{definition}[Partial linear Edelstein–Kelly configurations]
\label{def:linearek}
Let $c \in \bN$ , $0 < \delta \leq 1$ and $V$ be a $\bK$-vector space.
Let $\cF := \{v_1, \ldots, v_m\} \subset V$ be a finite set of pairwise linearly independent vectors.
We say that $\cF$ is a $\lrek{r}{\delta}$ configuration over $\bK$ if there exists a subset $\cG \subset \cF$ of size at most $r$, and a partition $\cF_{1} \cup \cF_{2} \cup \cF_{3}$ of the remaining forms $\cF \setminus \cG$ (with $\abs{\cF_{1}} \geq \abs{\cF_{2}} \geq \abs{\cF_{3}}$) such that the following condition holds:
\begin{itemize}
    \item for any $v \in \cF_{1}$ there are at least $\delta \abs{\cF_{2}}$ forms $u \in \cF_{2}$ such that $\abs{\Kspan{v, u} \cap \br{\cF_{3} \cup \cG}} \geq 1$. 
    \item for any $v \in \cF_{2}$ there are at least $\delta \abs{\cF_{1}}$ forms $u \in \cF_{1}$ such that $\abs{\Kspan{v, u} \cap \br{\cF_{3} \cup \cG}} \geq 1$. 
    \item for any $v \in \cF_{3}$ there are at least $\delta \abs{\cF_{1}}$ forms $u \in \cF_{1}$ such that $\abs{\Kspan{v, u} \cap \br{\cF_{2} \cup \cG}} \geq 1$. 
\end{itemize} 
\end{definition}

\begin{proposition}
    \label{prop:linearek}
    If $\cF$ is a $\lrek{r}{\delta}$ configuration then $\dim \Kspan{\cF} \leq r + c_{\mathrm{ek}} \cdot \delta^{-1} \log \br{\delta^{-1}}$ for a universal constant $c_{\mathrm{ek}}$.
\end{proposition}

\begin{definition}[High degree EK configurations]
\label{def:ek}
Let $U \subset S$ be a graded finitely generated vector space such that $R := S / \ideal{U}$ is a UFD, and let $z \in R_{1}$. 
Let $\cA, \cB, \cC \subset R$ be pairwise disjoint finite sets of irreducible forms of degree at most $d$.
We say that $\cA, \cB, \cC$ is a $(d, z, R)$-EK configuration if the following conditions hold: 
\begin{enumerate}
    \item $z \not\in \cA \cup \cB \cup \cC$, and the union $\{z\}\cup \cA \cup \cB \cup \cC$ consists of pairwise non-associate forms.
    \item For every $A \in \cA, B \in \cB$ we have
    $$ z \cdot \prod_{C \in \cC} C \in \radideal{A, B}.$$
    \item For every $A \in \cA, C \in \cC$ we have
    $$ z \cdot \prod_{B \in \cB} B \in \radideal{A, C}.$$
    \item For every $B \in \cB, C \in \cC$ we have
    $$ z \cdot \prod_{A \in \cA} A \in \radideal{B, C}.$$
\end{enumerate}
\end{definition}

\section{Strong Algebras}\label{sec:strongalg}

\subsection{Strength}

Let $R=\oplus_{d\geq 0} R_d$ be a finitely generated graded $\bK$-algebra,  generated by $R_1$. 
Henceforth, we refer to a homogeneous element of $R$ as a \emph{form}, adopting the same notation for polynomial rings.

\begin{definition}[Collapse]\label{def:collapse} 
Given a non-zero form $F \in R_d$, we say that $F$ has a \emph{$k$-collapse} if there exist $k$ forms $G_1, \ldots, G_k$ such that $1 \leq \deg(G_i) < d$ and $F \in (G_1, \ldots, G_k)$.
\end{definition}

\begin{definition}[Strength]\label{def:strength} 
Given a non-zero form $F \in R_d$, the \emph{strength} of $F$, denoted by $s(F)$, is the least positive integer such that $F$ has a $(s(F)+1)$-collapse but it has no $s(F)$-collapse.
We say that $s(F) \geq t$ whenever $F$ does not have a $t$-collapse.
\end{definition}

\begin{remark}
By the definitions above, a form $x\in R_1$ does not have a $k$-collapse for any $k \in \bN$. 
Thus, we say that for any $x \in R_1$, $s(x) = \infty$. In particular, linear forms in the polynomial ring $S$ have infinite strength.
We will make the convention that $s(0) = -1$.
\end{remark}

\begin{definition}[Min and max strength]\label{definition: smin smax}
Given a set of forms $F_1, \ldots, F_r \in R_d$,  define 
$\smin{F_1, \ldots, F_r}$ as the \emph{minimum} strength of a \emph{non-zero} form in $\Kspan{F_1, \ldots, F_r}$ and $\smax{F_1, \ldots, F_r}$ as the \emph{maximum} strength of a form in $\Kspan{F_1, \ldots, F_r}$. 

In particular, given any non-zero finite dimensional vector space $V \subset R_d$, define $\smin{V}$ ($\smax{V}$) as the minimum (maximum) strength of any non-zero form in $V$. If $V=(0)$, then there are no non-zero forms in $V$. In this case, by convention we define $\smin{(0)}=\smax{(0)}=\infty$.
We will say that a vector space $V$ is $k$-strong if $\smin{V}\geq k$. Note that the zero vector space is infinitely strong.
\end{definition}

\subsection{Strong Ananyan-Hochster Vector Spaces}\label{section: AH}

Let $R=\oplus_{d\geq 0} R_d$ be a finitely generated graded $\bK$-algebra, generated by $R_1$. 
Given a graded $\bK$-vector space $V = \bigoplus_{i=1}^d V_i \subset R$, where $\delta_i := \dim V_i$, we denote its dimension sequence by $\delta := (\delta_1, \ldots, \delta_d)$.

\begin{definition}[Strong Ananyan-Hochster vector spaces]\label{def:strong-AH-algebra} 
Let $R=\oplus_{d\geq 0} R_d$ be a finitely generated graded $\bK$-algebra, generated by $R_1$. 
For any function $B=(B_1,\cdots,B_d):\bN^d\rightarrow \bN^d$, we say that a non-zero graded vector subspace $V=\oplus_{i=1}^dV_i\subset R$, with dimension sequence $\delta$, is a $B$-strong AH vector space if $V_i$ is $B_i(\delta)$-strong for all $i$, i.e. $\smin{V_i}\geq B_i(\delta)$.  
The subalgebra $\bK[V]\subset R$ generated by a $B$-strong AH vector space $V$ is called a $B$-strong AH algebra.
\end{definition}

In the following lemma and the rest of this article, the function $A(\eta, d): \bN^{2} \to \bN$ is the function defined in \cite[Theorem A]{AH20}.

\begin{corollary}\label{corollary: strong sequence R_eta}
Let $V=\oplus_{i=1}^d V_i\subset S$ be a $B$-strong AH vector space for some $B:\bN^d\rightarrow \bN^d$.
Suppose $B_i(\delta)\geq A(\eta,i)+3(\sum_i\delta_i-1)$ for some $\eta\in \bN$. Then any sequence of $\bK$-linearly independent forms in $V$ is an $\mathcal{R}_\eta$-sequence. If $\eta\geq 3$, then $S/(V)$ is a Cohen-Macaulay, unique factorization domain.
\end{corollary}

\subsection{Lifted strength}

\begin{definition}[Lifted strength] 
Let $U\subset S$ be a graded vector space and $R=S/(U)$. 
Let $F\in R_d$ be a non-zero form. 
We define the lifted strength of $F$ with respect to $U$ as $$\lsmin{U,F}:=\min\{\smin{U_d+\Kspan{\widetilde{F}}}\}$$
where $\widetilde{F}$ varies over all forms in $S_d$ such that the image of $\widetilde{F}$ in $R$ is $F$. 
Given a set of forms $F_1,\cdots,F_m\in R_d$, we define $$\lsmin{U,F_1,\cdots,F_m}=\min\{\smin{U_d+\Kspan{\widetilde{F}_1,\cdots,\widetilde{F}_m}}\},$$ where $\widetilde{F}_i$ varies over all forms in $S_d$ such that the image of $\widetilde{F}_i$ in $R$ is $F_i$. 
Given a non-zero vector space $V\subset R_d$, we define $$\lsmin{U,V}=\min\{\lsmin{U_d,F_1,\cdots,F_m}\},$$ where $F_1,\cdots,F_m$ vary over all possible bases of $V$. 
We say that $V\subset R_d$ is $k$-lifted strong with respect to $U$ if $\lsmin{U,V}\geq k$. 
For simplicity, we omit $U$ from the notation and write $\lsmin{V}$ when $U$ is clear from the context. 

Suppose that $U\subseteq S_{\leq d}$ is of dimension sequence $\delta_U$. Let $V=\oplus_{i=1}^dV_i\subset R$ be a graded vector space of dimension sequence $\delta_V$.  
For any function, $B:\bN^d\rightarrow \bN^d$ we will say that $V$ is $B$-lifted strong with respect to $U$, if $V_i$ is $B_i(\delta_U+\delta_V)$-lifted strong, i.e. $\lsmin{U,V_i}\geq B_i(\delta_U+\delta_V)$ for all $i\in [d]$.  
In other words, $V$ is $B$-lifted strong with respect to $U$, if the vector space $U+\Kspan{\widetilde{F}_1,\cdots,\widetilde{F}_m}$ is $B$-strong in $S$, for any homogeneous basis $F_1,\cdots,F_m\in R$ of $V$ and any set of homogeneous lifts $\widetilde{F}_1,\cdots,\widetilde{F}_m\in S$.
\end{definition}

\subsection{Strengthening and Robustness}

For any $\mu\in \bN^d$, we define the translation function $t_\mu:\bN^d\rightarrow\bN^d$ as $t_\mu=(t_{\mu,1},\cdots, t_{\mu,d})$ where the $i$-th component is defined by $t_{\mu,i}(\delta)=\delta_i+\mu_i$. In other words, for all $i\in [d]$ we add $\mu_i$ to the $i$-th component of $\delta$. For any $n\in \bN$, we let $t_n:=t_{(n,\cdots,n)}$.

\begin{lemma}[Strengthening of Algebras]\label{proposition: constructing AH algebras} For any $d\in \bN$ and a function $B:\bN^d\rightarrow N^d$,
   there exist functions  $C_B:\bN^d\rightarrow\bN^d$ and $h_B:\bN^d\rightarrow\bN^d$, depending on $B$, such that the following holds:

    Given a graded vector space  $U=\oplus_{i=1}^dU_i\subset S$ with dimension sequence $\delta\in \bN^d$, there exists a $B$-strong AH vector space $V=\oplus_{i=1}^d V_i$ such that 
    \begin{enumerate}
        \item $\bK[U]\subset \bK[V]$,
        \item for all $i\in [d]$, we have $\dim(V_i)\leq C_{B,i}(\delta)$, where $C_{B,i}$ denotes the $i$-th component of $C_B=(C_{B,1},\cdots, C_{B,d}):\bN^d\rightarrow \bN^d$.
    \end{enumerate}

Furthermore, suppose   $H=\oplus_{i=1}^dH_i\subset U$ is a graded subspace such that $\smin{H_i}\geq h_{B,i}(\delta)$ for all $i\in [d]$. 
Then there exists a $B$-strong AH vector space $V$  satisfying (1) and (2) above such that $H\subset V$.
\end{lemma}

\begin{corollary}[Robustness of strong algebras]\label{corollary: robust strong algebra} Let $B,G:\bN^d\rightarrow\bN^d$ and $\mu\in\bN^d$. Suppose that $B_i(\delta)\geq h_{G,i}(\delta+\mu)$ for all $\delta\in \bN^d$ and $i\in [d]$, where $h_G:\bN^d\rightarrow \bN^d$ is the function defined in \cref{proposition: constructing AH algebras}. Let $U\subset S$ be a $B$-strong AH vector space and $W\subset S$ is a graded vector space with dimension sequences $\delta$ and $\mu$ respectively. Then there exists a $G$-strong AH vector space $V$ such that 
\begin{enumerate}
    \item $\bK[U+W]\subset\bK[V]$,
    \item $U\subset V$,
    \item for all $i\in [d]$, $\dim(V_i)\leq C_{G,i}(\delta+\mu)$, where $C_G:\bN^d\rightarrow \bN^d$ is the function defined in \cref{proposition: constructing AH algebras}.
\end{enumerate}
\end{corollary}

\begin{corollary}\label{corollary: practical robustness}
 Let $B:\bN^d\rightarrow \bN^d$. Let $U\subset S$ be a graded vector space with dimension sequence $\delta_U\in \bN^d$ and let $R=S/(U)$. Let $V\subset R$ is a graded vector space with dimension sequence $\delta_V\in \bN^d$. Suppose $V$ is  $h_{2B}\circ t_k$-lifted strong with respect to $U$. Let $P_1,\cdots,P_k\in R_{\leq d}$ be homogeneous elements. Then there exists a graded vector space $V'\subset R_{\leq d}$ such that:

\begin{enumerate}
    \item $V'$ is $B$-lifted strong with respect to $U$.
    \item $P_1,\cdots,P_k\in \bK[V']$.
    \item $V\subset V'$.
    \item for all $i\in [d]$, we have $\dim(V'_i)\leq C_{2B,i}(t_k(\delta_U+\delta_V))-\delta_{U,i}$. In particular, $\dim(V')\leq C(B,\delta_U,\delta_V,k):=\sum(C_{2B,i}(t_k(\delta_U+\delta_V))-\delta_{U,i})$.
\end{enumerate}
\end{corollary}

\begin{definition}[Ananyan-Hochster spaces]\label{def: AH-process}
    In the situation of \cref{corollary: robust strong algebra}, we define $AH(U,W)$ to be any graded vector space $V$ provided by \cref{corollary: robust strong algebra}.
    Similarly, in the situation of \cref{corollary: practical robustness}, we define $AH_R(V,P_1,\cdots,P_k)$ to be any vector space $V'$ provided by \cref{corollary: practical robustness}.
\end{definition}

\begin{remark}
    Note that, for given $V,P_1,\cdots,P_k$, the vector space $AH_R(V,P_1,\cdots,P_k)$ is not necessarily unique. 
    As stated in our definition, we use the notation $AH_R(V,P_1,\cdots,P_k)$ to denote any vector space satisfies the properties in \cref{corollary: practical robustness}, whose existence is guaranteed. 
    We will only use these properties of these spaces and in all our arguments we work with any fixed choice of such a vector space $AH_R(V,P_1,\cdots,P_k)$. 
\end{remark}

\begin{definition}[$(k,t)$-process]
    Let $U \subseteq S$ be a graded finitely generated vector space such that $R := S / \ideal{U}$ is a UFD, and $k, t \geq 1$ be integers.
    Let $V \subseteq R$ be a vector space and let $\cF \subseteq R$.
    A $(k, t)$ process on $V$ is defined to be a process that starts with the vector space $V$, and performs at most $t$ rounds.
    In each round, at most $k$ forms $F_{1}, \dots, F_{k}$ of degree at most $d$ are picked from the set $\cF$, and $V$ is updated to $AH_R(V, F_{1}, \dots, F_{k})$.
    In each iteration, the picked forms are allowed to be chosen based on the new $V$.
    Note that we are dropping the dependence on $d$ from the notation for convenience, as $d$ will always be clear from context.
\end{definition}

\emph{Strength bound function.} Given a function $B: \bN^d\rightarrow \bN^d$, and positive integers $k, t$, we define a function $H(B, k, t): \bN^d\rightarrow \bN^d$ recursively as follows.
Let $H(B, k, 0) := B$, and \[H(B, k, t) := h_{2 H(B, k, t-1)} \circ t_{k + 1}, \] where $h$ is as defined in \cref{proposition: constructing AH algebras}.

\emph{Dimension bound function.} Fix $\delta \in \bN^{d}$, and $B,k,t$ as above. We define a function $D(B, k, t, \delta) : \bN^{d} \to \bN^{d}$ recursively as follows.
Let $D(B, k, 0, \delta)$ be the identity function.
To define $D(B, k, t, \delta)(\mu)$, assuming  $D(B, k, t-1, \delta)$ is already defined, we first define \[\eta := \max_{\substack{x\in \bN^d\\ \norm{x}_{1} = \norm{\mu}_{1}}} \norm{D(B, k, t-1, \delta)(x)}_{1},\]
where $\norm{x}_1=x_1+\cdots+x_d$ for $x=(x_1,\cdots,x_d)\in \bN^d$.
We then define the $i^{th}$ coordinate function $D_{i}(B, k, t, \delta)(\mu)$ as
$$ D_{i}(B, k, t, \delta)(\mu) = \max_{x, \norm{x}_{1} = \eta} C_{2 H(B, k, t), i}(t_{k+1} (x + \delta)),$$
where again $C$ is the function defined in \cref{proposition: constructing AH algebras}.

\begin{lemma}
    \label{lem: iterated lifted strength}
     Let $U \subseteq S$ be a graded finitely generated vector space such that $R := S / \ideal{U}$ is a UFD, and $k, t, k', t' \geq 1$ be integers.
     \begin{enumerate}
        \item The composition of a $(k, t)$ process and a $(k', t')$ process is a $(\max\br{k, k'}, r + r')$ process.
        \item If $V$ is $H(B, k, t)$-lifted strong, and if $V'$ is the result of a $(k, t)$ process on $V$, then $V \subset V'$ and $V'$ is $B$-lifted strong.
        Moreover, each intermediate vector space that appears as part of the process is $h_{2B} \circ t_{1}$-lifted strong.
        \item If $V'$ is the result of a $(k, t)$ process on $V$, then the dimension of $V'$ is bounded by $D(B, k, t, \delta_{U})(\delta_{V})$, where $\delta_{U}, \delta_{V}$ are the dimension vectors of $V, U$ respectively.
\end{enumerate}
\end{lemma}

\subsection{Absolute irreducibility with respect to strong vector spaces}
\label{subsec:absirredstrong}

\begin{definition}
    \label{def:absred}
    Let $B:\bN^d\rightarrow \bN^d$.
    Suppose $B_i(\delta)\geq A(\eta,i)+3(\sum_i\delta_i-1)$ for some $\eta\in \bN$.
    Suppose $R = S / \ideal{U}$.
    Suppose $V \subset R$ is a graded vector space that is $h_{2B} \circ t_{1}$-lifted strong with respect to $U$.
    Suppose $P \in R$ is a form.
    Let $V'$ be the vector space obtained by applying \cref{corollary: practical robustness} to $V$ and $P$.
    Let $y_{1}, \dots, y_{a}$ be a basis of homogeneous forms of $V$, and $y_{a+1}, \dots, y_{b}$ extend this to a basis of $V'$.
    We say $P$ is absolutely reducible over $V$ if $P$ is absolutely reducible as a polynomial in $\bK\br{y_{1}, \dots, y_{a}}\bs{y_{a+1}, \dots, y_{b}}$.
\end{definition}

The functions $\primebound{d}, \irredprimebound{d} : \bN \to \bN$ referred to in the following lemma is the same functions whose existence is guaranteed by \cref{lem:primebound}, \cref{cor:absredspan} respectively.

\begin{corollary}[Corollary of \cref{lem:primebound}, \cref{cor:absredspan}]
    \label{cor:strongprimebound}
    Let $B:\bN^d\rightarrow \bN^d$.
    Suppose $B_i(\delta)\geq A(\eta,i)+3(\sum_i\delta_i-1)$ for some $\eta\in \bN$.
    Suppose $R = S / \ideal{U}$.
    Suppose $V \subset R$ is a graded vector space that is $h_{2B} \circ t_{1}$-lifted strong with respect to $U$.
    Suppose $P \in R$ is absolutely irreducible with respect to $V$ such that $\deg P = d$.
    There are at most $\primebound{d}$ irreducible non-associate forms $Q_{i} \in \bK\bs{V}$ such that $\ideal{Q_{i}, P}$ is not prime.
    Further, there are at most $\irredprimebound{d}$ pairwise non-associate degree $d$ irreducible forms $H_{i} \in \bK\bs{V}$ such that $\Kspan{P, H_{i}} \setminus \bc{H_{i}}$ contains a form that is absolutely reducible over $V$.
\end{corollary}

\section{Graded Quotients}\label{sec:generalquot}

Throughout this section, we fix positive integers $d,\eta\in \bN$ with $\eta\geq 3$.
Throughout this section, $B:\bN^d\rightarrow \bN^d$ denotes an ascending function such that $B_i(\delta)\geq A(\eta,i)+3(\sum_i\delta_i-1)$ for all $i\in [d]$. Here $A(\eta, i)$ is the function defined in \cref{section: AH}.

\begin{definition}[Graded Quotients]\label{definition: quotients}
Let $U=\oplus_{i=1}^d U_i\subset S$ be a graded vector space of dimension sequence $\delta$ in $S$ and $R := S/(U)$ be the quotient ring. 
Let $V=\oplus_{i=1}^dV_i \subset R$ be a graded subspace of dimension sequence $\mu$.

Let $F_1, \ldots, F_n$ be a homogeneous basis for $V$ and $z$ be a new variable. 
For $\alpha \in \bK^n$, let $I_\alpha\subseteq R[z]$ be the homogeneous ideal generated by the forms $ \{F_1 - \alpha_1 z^{\deg(F_1)}, \dots, F_n - \alpha_n z^{\deg(F_n)}\}$. 
We define the graded quotient map $\varphi_{V, \alpha}$ as the quotient homomorphism of finitely generated graded $\bK$-algebras given by
$$ \varphi_{V, \alpha} : R[z] \to R[z]/I_\alpha. $$
\end{definition}

\begin{remark}
The definition above depends on the choice of the basis $F_1,\cdots,F_n$ for $V$. We omit this from the notation for simplicity. We will apply this graded quotient construction for sufficiently strong vector spaces $V$. Therefore \cite{AH20} shows that any basis of $V_\alpha$ forms an $\cR_\eta$ sequence. Similarly, several of our statements regarding these graded quotients will apply independent of the choice of the basis. However, for certain applications we will deal with explicit choices of bases and we define the notion of compatible graded quotients in that context (\cref{def: compatible quotients}).
\end{remark}

\emph{General points.} We say that a property $\mathcal{P}$ holds for a \emph{general} $ \alpha \in \bK^m$, if there exists a non-empty open subset $\cU \subseteq\bK^m$ such that the property $\mathcal{P}$ holds for all $\alpha\in \cU$. Here $\cU \subseteq \bK^m$ is open with respect to the Zariski topology. 
Hence $\cU$ is the complement of the zero set of finitely many polynomial functions on $\bK^m$. Note that, equivalently a property $\cP$ holds for a general $\alpha\in \bK^m$, if there is a closed subset $\cZ\subseteq \bK^m$ such that the $\cP$ holds for all $\alpha\not \in \cZ$.

\begin{proposition}\label{proposition: general quotient general}
Let $V \subset R$ be a $B$-lifted strong vector space and $\varphi_\alpha :R[z]\rightarrow R[z]/I_\alpha$ be a graded quotient as defined in \cref{definition: quotients}.
\begin{enumerate}
    \item The ideal $I_\alpha$ is a prime ideal in $R[z]$ and the composition $\bK[z]\hookrightarrow R[z]\rightarrow R[z]/I_\alpha$ is injective.
    \item  If  $F \in R \setminus \{0\}$, then $\varphi_\alpha(F)\neq 0$ for a general $\alpha\in \bK^n$.
    \item  If $F\not\in \bK[V] \subset R$, then $\varphi_\alpha(F)\not\in \bK[z]$ for a general $\alpha\in \bK^n$.
    \item If $F\not \in (V)$ then $\varphi_\alpha(F)\not \in (z)$ in $R[z]/I_\alpha$.
    \item If $F$ is absolutely reducible with respect to $V$ then $\varphi_{\alpha}(F)$ is a reducible form in $R[z]/I_\alpha$ for general $\alpha$.
    \item If $F$ is absolutely irreducible with respect to $V$ and $F\not\in (V)$, then $\varphi_\alpha(F)$ is irreducible for general $\alpha$.
\end{enumerate}
\end{proposition}

\begin{proposition}\label{proposition: gcd after projection}
Let $G:\bN^d\rightarrow \bN^d$ be a function such that $G_i(\delta)\geq h_{B,i}\circ t_2(\delta)$ for all $\delta\in \bN^d$. 
Let $V \subset R_{\leq d}$ be a $G$-lifted strong vector space and $\varphi_\alpha :R[z]\rightarrow R[z]/I_\alpha$ be a graded quotient as defined in \cref{definition: quotients}. 
Let $F, G \in R_{\leq d}$ be such that they have no common factor.
There exists a non-empty open subset $\cU\subseteq \bK^{\dim(V)}$ such that for all $\alpha\in \cU$ we have:
\begin{enumerate}
    \item $\gcd(\varphi_\alpha(F), \varphi_\alpha(G)) \in \bK[z]$. \item If $F,G$ are homogeneous, then 
