\subsection{Compatible graded quotients and twisted quotients}

\begin{definition}[Compatible graded quotients]\label{def: compatible quotients}
    Let $R=S/(U)$ and $V, Y\subseteq R$ be finite dimensional $\bK$-vector spaces such that $V\subseteq Y$. Let $\cF_V,\cF_Y$ be $\bK$-linear bases of $V,Y$ respectively. We say that $\cF_V,\cF_Y $ are compatible bases if $\cF_V \subseteq \cF_Y$. 

   Consider the compatible bases given by $\cF_V=\{F_1,\cdots,F_m\}$ and $\cF_Y=\{F_1,\cdots,F_m,G_1,\cdots,G_n\}$. Let $\alpha\in \bK^m$,$\beta\in \bK^n$ and let $y_1,y_2$ be new variables. Let $\varphi_{V,\alpha}:R[y_1]\rightarrow R[y_1]/I_{V,\alpha}$ be the graded quotient given by $F_i\mapsto \alpha_iy_1^{\deg(F_i)}$. Let $\varphi_{Y,(\alpha,\beta)}:R[y
   _1]\rightarrow R[y_1]/I_{Y,(\alpha,\beta)}$ be the graded quotient that sends $F_i\mapsto \alpha_iy_1^{\deg(F_i)}$ and $G_j\mapsto \beta_jy_1^{\deg(G_j)}$. Then we will say that $\varphi_{V,\alpha}$ and $\varphi_{Y,(\alpha,\beta)}$ are compatible graded quotients.

   \end{definition}

\begin{definition}[Twists] Let $\gamma\in \bK^*$ and $d_1,\cdots,d_n\in\bN$. For $\beta\in\bK^n$, we define the twist of $\beta$ by $\gamma$ as the natural action of the torus given by $\gamma \cdot \beta=(\gamma^{d_1}\beta_1,\cdots,\gamma^{d_n}\beta_n)$. 

\end{definition}

\begin{definition}[Twisted quotient]
Let $V\subseteq R$ with a basis $\{F_1,\cdots,F_n\}$ and $\beta\in \bK^n$. For $\gamma\in\bK^*$, we will say that the graded quotient $\varphi_{V,\gamma\cdot \beta}$ is the $\gamma$-twist of the graded quotient $\varphi_{V,\beta}$.

\end{definition}

\begin{proposition}\label{prop: composition of quotient}
    Let $R=S/(U)$ and $V, Y\subseteq R$ be finite dimensional $\bK$-vector spaces such that $V\subseteq Y$. Let $\alpha\in \bK^{\dim(V)}$ and $\beta\in \bK^{\dim(Y)-\dim(V)}$. Let $\varphi_{V,\alpha}$ and $\varphi_{Y,(\alpha,\beta)}$ be compatible graded quotients with compatible bases $\cF_V\subseteq \cF_Y$. Let $Y'=\Kspan{\cF_Y\setminus \cF_V}$. We denote $Y'_\alpha=\varphi_{V,\alpha}(Y')\subseteq R'_\alpha$, where  $R'_\alpha:=R[y]/I_{V,\alpha}$. Let $Y_\alpha=\Kspan{y_1,Y'_\alpha}$. Then the following holds.
    \begin{enumerate}
        \item Let $B:\bN^d\rightarrow \bN^d$ be such that $B_k(\delta+\mu)\geq B_k(\delta)+\norm{\mu}_1$ for all $\delta,\mu \in \bN^d$. If $Y$ is $B$-lifted strong, then $Y'_\alpha$ is also $B$-lifted strong.
        \item Let $\gamma\in \bK^*$. For a general $\alpha$, we have a commutative diagram of $\bK$-algebra homomorphisms.

        \[\begin{tikzcd}
 R[y_1] \arrow[r, "\varphi_{V,\alpha}"] \arrow[d, "id"] & R'_\alpha\arrow[rr,"\varphi_{Y_\alpha,\gamma\cdot(1,\beta)}"] & & R'_\alpha[y_2]/I_{Y_\alpha,\gamma\cdot(1,\beta)} \arrow[d,"\simeq"]\\
 R[y_1] \arrow[rrr, "\varphi_{Y,(\alpha,\beta)}"] & & &   R[y_1]/I_{Y,(\alpha,\beta)} \\
\end{tikzcd}\] 
where the map $\varphi_{Y_\alpha,\gamma\cdot(1,\beta)}$ sends $y_1\mapsto \gamma  y_2$ and on $Y'_\alpha$ it is same as the twisted quotient $\varphi_{Y'_\alpha,\gamma\cdot \beta}$. Moreover, the vertical isomorphism sends $y_2\mapsto \frac{1}{\gamma} y_1$.
    \end{enumerate}
\end{proposition}

