\subsection{Potential function}\label{subsection: potential function}

Let $U \subseteq S$ be a graded finitely generated vector space such that $R := S / \ideal{U}$ is a CM UFD.
Let $V \subseteq R$ be a $h_{2B} \circ t_{1}$-lifted strong vector space and $\alpha \in \bK^{\dim(V)}$.
The quotient map $\varphi_{V,\alpha}: R[y] \rightarrow R[y] / I_{V,\alpha}$ is defined in \cref{sec:generalquot}. 

\emph{Individual potential.} For a form $F \in R$, let $\varphi_{V,\alpha}(F)=y^{r} \prod_{i=1}^{s}F_{i}^{r_i}$ be an irreducible factorization.
We define the potential of $F$ with respect to $V$ and $\alpha$ as 
\[ \psi_{V,\alpha}(F)=2r+s. \]

\emph{Group potential.} For a finite set of forms $\cG \subseteq R$, we define the potential of $\cG$ with respect to the pair $(V,\alpha)$ as 
\[\Phi_{V,\alpha}(\cG)=\sum_{G\in\cG}\psi_{V,\alpha}(G).\]

\begin{remark}\label{remark: group potential bound}
    Note that if $\cG\subseteq R_{\leq d}$, then $\Phi_{V,\alpha}(\cB)\leq 2d|\cB|$ for any $(V,\alpha)$.
\end{remark}

\emph{Potential increasing forms.} Let $V\subseteq Y$ be both $h_{2B}\circ t_1$-lifted strong vector spaces in $R$. Let $\alpha\in \bK^{\dim(V)}$ and $\beta\in \bK^{\dim(Y)-\dim(V)}$. We say that $F\in \cG$ is a \textit{potential increasing} form with respect to the pairs $(V,\alpha)$ and $(Y,(\alpha,\beta))$ if 
\[\Psi_{Y,(\alpha,\beta)}(F)> \Psi_{V,\alpha}(F).\]

\begin{lemma}[Potential increasing criterion]\label{lemma: abs red and potential increase}
    Let $V\subseteq Y$ be both $h_{2B}\circ t_1$-lifted strong vector spaces in $R$ of dimensions $m$ and $m+n$ respectively. Let $\varphi_{V,\alpha}$ and $\varphi_{Y,(\alpha,\beta)}$ be compatible graded quotients with respect to bases $\cF_V\subseteq \cF_Y$. Let $Y'=\Kspan{\cF_Y\setminus \cF_V}$, $R'_{\alpha}=R[y_1]/I_{V,\alpha}$, $Y'_\alpha=\varphi_{V,\alpha}(Y')$ and $Y_\alpha=\Kspan{y_1,Y'_\alpha}$.

    Let $F\in R$ be a square-free form. Let $\alpha\in \bK^m$ be a general element. Suppose that there exists a factor $F_k$ of $\varphi_{V,\alpha}(F)$ in $R'_\alpha$, such that
    \begin{enumerate}
        \item $F_k$ is not a scalar multiple of $y_1$, and
        \item $F_k$ is absolutely reducible with respect to $Y_\alpha$ or $F_k$ is in the ideal $(Y_\alpha)$ in $R'_\alpha$.
    \end{enumerate}

    Then there exists a non-empty open subset $\cU\subseteq \bK^n$ (depending on $\alpha$) such that for all $\beta\in \cU$, the form $F$ is potential increasing with respect to the pairs $(V,\alpha)$ and $(Y,(\alpha,\beta))$.
\end{lemma}

